bench( format( '%s::set,get:encode', pkg ), function benchmark( b ) {
	var values;
	var v;
	var i;

	values = [
		{
			'labels': {
				'update': {
					'fill': {
						'value': 'red'
					}
				}
			}
		},
		{
			'labels': {
				'update': {
					'fill': {
						'value': 'blue'
					}
				}
			}
		}
	];
	v = new Legend({
		'fill': 'colorScale'
	});

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v.encode = values[ i % values.length ];
		if ( typeof v.encode !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isPlainObject( v.encode ) ) {
		b.fail( 'should return an object' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

